import 'package:flutter_agent_harness/flutter_agent_harness.dart';
import 'package:flutter_agent_harness/io.dart';
import 'package:test/test.dart';

import 'test/cli/agent_cli_test_support.dart' show FakeSecureKeyStore;

void main() {
  test('probe: project-config queue with env-only keys -> boot diagnostics',
      () async {
    final saved = CliConfig();
    final keys = SecureKeyCache(FakeSecureKeyStore());
    final report = await keys.preload(
      secureKeyPreloadNames(saved, baseUrl: null, queueEntries: [
        ProviderQueueEntry(
          providerType: 'zai',
          model: 'glm-5.3-flash',
          apiKeyEnv: 'MY_ENV_ONLY_KEY',
          baseUrl: 'https://api.z.ai/api/coding/paas/v4',
        ),
      ]),
    );
    final lines = secureKeyBootDiagnostics(
      report: report,
      referencedKeyNames: referencedSecureKeyNames(saved, queueEntries: [
        ProviderQueueEntry(
          providerType: 'zai',
          model: 'glm-5.3-flash',
          apiKeyEnv: 'MY_ENV_ONLY_KEY',
          baseUrl: 'https://api.z.ai/api/coding/paas/v4',
        ),
      ]),
      debug: false,
    );
    // ignore: avoid_print
    print('DIAG LINES: $lines');
    expect(lines, isEmpty, reason: 'env-sourced queue key must not warn');
  });
}

